// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"tr","term":"Ethereum (ETH)","aka":["ETH","Ether","Ethereum"],"short":"Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır.","body":[[["Bitcoin","bitcoin"]," büyük ölçüde değer transferine odaklanırken Ethereum bir tür küresel bilgisayar gibi çalışır. Geliştiriciler buraya ",["akıllı kontrat","smart-contract"]," adı verilen programlar yükler. Merkeziyetsiz borsalar (",["DEX","dex"],"), borç verme protokolleri, ",["NFT","nft"],"'ler ve binlerce token bu kontratlar sayesinde var olur."],["Ethereum'da her işlem ",["gas ücreti","gas-fee"]," gerektirir ve bu ücret ETH ile ödenir. Ağ yoğunlaştığında ücretler yükselir. Bu nedenle Arbitrum, Optimism ve Base gibi layer 2 ağları, işlemleri daha ucuza yapıp sonucu Ethereum'a kaydeder."],"Eylül 2022'deki Merge ile Ethereum iş ispatından hisse ispatına geçti. Artık blokları madenciler değil, ETH stake eden validatörler üretir. Ayrıca işlem ücretinin temel kısmı yakıldığı için ETH arzı, ağ kullanımına bağlı olarak artabilir ya da azalabilir."],"example":["ETH'nin 3.000 ",["USDT","usdt"]," olduğunu ve Ethereum ana ağında bir token takası yapmak istediğinizi düşünün. Cüzdanınız işlem için 150.000 gas birimi ve gwei cinsinden 10 gwei ücret öngörüyor. Ücret 150.000 x 10 = 1.500.000 gwei, yani 0,0015 ETH eder; bu da yaklaşık 4,5 USDT demektir. Ağ yoğunluğunda ücret 40 gwei'ye çıkarsa aynı işlem 0,006 ETH, yani yaklaşık 18 USDT tutar. Aynı takası bir layer 2'de yapmak çoğu zaman bunun küçük bir kısmına mal olur."],"mistakes":["Cüzdanda hiç ETH bırakmayıp token gönderirken gas ödeyememek.","Ethereum ana ağı ile layer 2 ağlarını karıştırıp yanlış ağa transfer yapmak.","Ethereum ile Ethereum Classic'i (ETC) aynı varlık sanmak."],"faq":[{"q":"Ethereum ile Ether arasındaki fark nedir?","a":"Ethereum ağın adıdır, Ether (ETH) ise bu ağın yerel coinidir. Günlük kullanımda ikisi de çoğu zaman Ethereum diye anılır."},{"q":"Ethereum hâlâ madencilikle mi çalışıyor?","a":"Hayır. Eylül 2022'deki Merge'den beri Ethereum hisse ispatı kullanıyor ve blokları ETH stake eden validatörler üretiyor."},{"q":"Ethereum'un arz sınırı var mı?","a":"Bitcoin gibi sabit bir üst sınırı yoktur. Yeni ETH staking ödülleriyle çıkar, ancak işlem ücretlerinin bir kısmı yakıldığı için net arz dönemden döneme değişir."}],"title":"Ethereum (ETH) nedir? Ne işe yarar?","description":"Ethereum'un ne olduğunu, ETH'nin gas ücretleri ve staking'deki rolünü ve layer 2 ağlarıyla ilişkisini öğrenin.","related":[["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."],["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır."],["layer-2","Katman 2 (Layer 2, L2)","Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır."],["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"tr","term":"Katman 1 (Layer 1, L1)","aka":["L1","layer 1","ana ağ","katman 1 blockchain"],"short":"Katman 1 (Layer 1, L1), işlemleri kendi başına doğrulayıp kesinleştiren, kendi uzlaşma mekanizmasına ve yerel coinine sahip temel blockchain ağıdır; Bitcoin, Ethereum ve Solana buna örnektir.","body":[["Bir L1, güvenliği başka bir zincire dayanmadan sağlar. İşlemler kendi validatörleri veya madencileri tarafından onaylanır ve ücretler kendi coiniyle ödenir: ",["Bitcoin","bitcoin"],"'de BTC, ",["Ethereum","ethereum"],"'da ETH, Solana'da SOL."],["L1'ler genellikle ",["blockchain","blockchain"]," üçlemi denen dengeyle uğraşır: merkeziyetsizlik, güvenlik ve ölçeklenebilirlik aynı anda en üst düzeyde zor sağlanır. Bitcoin ve Ethereum merkeziyetsizlik ve güvenliğe öncelik verir; bazı yeni L1'ler daha yüksek hız ve düşük ücret için farklı tasarım tercihleri yapar."],"Ethereum'un yaklaşımı, ölçeklemeyi büyük ölçüde layer 2 ağlarına bırakmaktır. Kullanıcı açısından L1 ile L2 arasındaki fark en çok ücretlerde, onay sürelerinde ve borsadan çekim yaparken seçtiğiniz ağda kendini gösterir."],"example":["Aynı 100 ",["USDC","usdc"],"'yi iki farklı yoldan göndermek istediğinizi düşünün. Ethereum L1'de yoğun bir saatte ",["transfer ücreti","withdrawal-fee"]," örneğin 3 USDC tutabilir; bu, tutarın yüzde 3'ü demektir. Aynı transferi bir Ethereum L2'sinde yaparsanız ücret 0,05 USDC civarında olabilir, yani yüzde 0,05. Bir başka L1 olan Solana'da ücret çoğu zaman bir sentin altındadır. Ücretlerin hangi ağı kullandığınıza göre bu kadar değişmesi, çekim ekranında ağ seçimini önemli kılar."],"mistakes":["Bir token'ın her L1'de aynı adreste ve aynı kontratla bulunduğunu varsaymak.","Ağ ücretlerini yalnızca bir anlık değere bakarak değerlendirmek; ücretler yoğunluğa göre hızla değişir.","Bir L1'in hızını tek başına güvenlik veya merkeziyetsizlik göstergesi sanmak."],"faq":[{"q":"Hangi blockchain'ler Layer 1?","a":"Bitcoin, Ethereum, Solana, BNB Chain, Avalanche, Cardano ve Tron yaygın örneklerdir. Her birinin kendi uzlaşma mekanizması ve yerel coini vardır."},{"q":"L1 ile L2 arasındaki fark nedir?","a":"L1 kendi güvenliğini sağlayan temel zincirdir. L2 ise işlemleri ayrı yürütüp sonuçları bir L1'e kaydederek onun güvenliğinden yararlanır."}],"title":"Layer 1 (L1) nedir? Katman 1 blockchain anlamı","description":"Layer 1 blockchain'in ne olduğunu, L2'den farkını ve ağ seçiminin transfer ücretlerini nasıl etkilediğini öğrenin.","related":[["layer-2","Katman 2 (Layer 2, L2)","Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."],["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır."],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."],["coin-vs-token","Coin ve token farkı","Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi)."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"tr","term":"Token yakımı (token burn)","aka":["token burn","coin yakma","burn"],"short":"Token yakımı (token burn), token'ların kimsenin erişemeyeceği bir adrese gönderilerek veya kontrat tarafından imha edilerek dolaşımdan kalıcı olarak çıkarılmasıdır.","body":[["Yakılan token'lar özel anahtarı bilinmeyen bir adrese (burn adresi) gönderilir veya kontrat toplam arzdan doğrudan düşer. İşlem ",["blockchain","blockchain"],"'de görünür olduğu için herkes doğrulayabilir. Sonuç olarak dolaşımdaki ve toplam arz azalır."],["Yakım farklı şekillerde yapılır. BNB için düzenli aralıklarla yakım programı uygulanır. ",["Ethereum","ethereum"],"'da her işlemin temel ücreti otomatik olarak yakılır. Bazı projeler ise gelirlerinin bir kısmıyla piyasadan token geri alıp yakar."],"Arz azalması, talep sabit kalırsa her bir token'ın payını büyütür; ama fiyatı tek başına belirleyen bir etken değildir. Yakılan miktarın toplam arza ve yeni basılan token'lara oranı önemlidir. Küçük bir yakım, büyük bir enflasyon veya kilit açılımı karşısında etkisiz kalabilir."],"example":["Toplam arzı 200 milyon olan bir token'ın, bir çeyrekte 2 milyon token yaktığını düşünün. Bu, arzın yüzde 1'idir ve yeni arz 198 milyon olur. Fiyat 5 ",["USDT","usdt"],"'de sabit kalırsa ",["piyasa değeri","market-capitalization"]," 1 milyar USDT'den 990 milyon USDT'ye iner; piyasa değeri sabit kalırsa fiyat 1.000.000.000 / 198.000.000 = yaklaşık 5,05 USDT olur. Ancak aynı çeyrekte ",["staking","staking"]," ödülleriyle 3 milyon yeni token basılıyorsa net arz 1 milyon artmış olur."],"mistakes":["Her yakım duyurusunun fiyatı yükselteceğini varsaymak.","Yakılan miktarı yeni basılan veya kilidi açılan token'larla karşılaştırmamak.","Token'ları kendi cüzdanınızdan yanlışlıkla bir burn adresine gönderip geri alınabileceğini sanmak."],"faq":[{"q":"Token yakımı neden yapılır?","a":"Arzı azaltmak, protokol gelirini token sahiplerine dolaylı olarak yansıtmak veya bir ağın ücret modelinin parçası olarak yapılır. Amaç ve yöntem projeden projeye değişir."},{"q":"Yakılan token'lar geri getirilebilir mi?","a":"Gerçek bir burn adresine gönderilen token'lar kimse tarafından harcanamaz ve geri getirilemez. Bu yüzden yakım kalıcı kabul edilir."}],"title":"Token yakımı (burn) nedir? Fiyatı etkiler mi?","description":"Token yakımının nasıl yapıldığını, arzı nasıl azalttığını ve neden tek başına fiyat artışı anlamına gelmediğini öğrenin.","related":[["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."],["circulating-supply","Dolaşımdaki arz (circulating supply)","Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır."],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."],["coin-vs-token","Coin ve token farkı","Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi)."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"tr","term":"FUD (korku, belirsizlik ve şüphe)","aka":["FUD","fud yaymak"],"short":"FUD (fear, uncertainty and doubt), bir kripto para veya proje hakkında korku, belirsizlik ve şüphe yaratan haberler, söylentiler ya da yorumlar için kullanılan bir terimdir.","body":["FUD bazen kasıtlı olarak, fiyatı düşürmek veya bir rakibi kötülemek için yayılır. Bazen de gerçek bir sorunun ilk sinyalidir. Kripto topluluklarında bir coinin destekçileri her olumsuz haberi FUD diye geçiştirebilir; bu da tehlikelidir.","Bir haberi değerlendirirken kaynağı kontrol etmek gerekir: resmi bir duyuru mu, doğrulanmış bir haber kuruluşu mu, yoksa anonim bir hesap mı? Zincir üstü veriler (büyük cüzdan hareketleri, borsa rezervleri) ve projenin resmi açıklamaları, söylentiyi gerçekten ayırmaya yardımcı olur.","FUD dönemlerinde fiyatlar ani düşebilir ve panik satışlar görülebilir. Önceden belirlenmiş bir plan, bir haberin gerçekten yatırım gerekçenizi değiştirip değiştirmediğini sakin biçimde değerlendirmenize yardım eder."],"example":["Sosyal medyada bir borsanın çekimleri durdurduğu söylentisi yayılıyor ve borsanın token'ı bir saat içinde 10 ",["USDT","usdt"],"'den 8,5 USDT'ye, yani yüzde 15 düşüyor. 200 token tutan biri için değer 2.000'den 1.700 USDT'ye iniyor. Panikle satmadan önce borsanın resmi duyurularına ve zincir üstü çekim verilerine baktığınızda çekimlerin planlı bir cüzdan bakımı nedeniyle 30 dakika durduğunu görüyorsunuz. Tersine, resmi kanal sessiz kalıyor ve zincir üstünde çekimler gerçekten duruyorsa, bu kez söylenti ciddi bir uyarı olabilir."],"mistakes":["Her olumsuz haberi doğrulamadan FUD diye görmezden gelmek.","Anonim bir paylaşıma dayanarak panikle zararına satış yapmak.","Kaynağı kontrol etmeden söylentiyi paylaşıp yayılmasına katkıda bulunmak."],"faq":[{"q":"FUD ne demek?","a":"Korku, belirsizlik ve şüphe anlamına gelen İngilizce ifadenin kısaltmasıdır. Bir varlık hakkında olumsuz duygu yaratan bilgi veya söylentileri tanımlar."},{"q":"FUD ile gerçek risk nasıl ayırt edilir?","a":"Resmi duyurulara, güvenilir haber kaynaklarına ve zincir üstü verilere bakın. Doğrulanabilen somut bir bilgi varsa bunu gerçek bir risk olarak değerlendirmek gerekir."}],"title":"FUD nedir? Kriptoda FUD ne demek?","description":"FUD'un ne anlama geldiğini, söylentiyi gerçek riskten nasıl ayıracağınızı ve panik satıştan nasıl kaçınacağınızı öğrenin.","related":[["fomo","FOMO (fırsatı kaçırma korkusu)","FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir."],["bear-market","Ayı piyasası (bear market)","Ayı piyasası (bear market), fiyatların uzun bir dönem boyunca genel olarak düştüğü, yatırımcı karamsarlığının ve düşük ilginin hakim olduğu piyasa evresidir."],["fear-and-greed-index","Korku ve Açgözlülük Endeksi (Fear and Greed Index)","Korku ve Açgözlülük Endeksi, kripto piyasasındaki genel duyguyu 0 ile 100 arasında tek bir sayıyla gösteren; 0 aşırı korkuyu, 100 aşırı açgözlülüğü ifade eden bir göstergedir."],["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"tr","term":"Alış-satış makası (spread)","aka":["spread","makas","alım satım makası","bid-ask spread"],"short":"Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir.","body":["Bir coini anında almak istediğinizde en düşük satış fiyatından alırsınız; anında satmak istediğinizde en yüksek alış fiyatından satarsınız. Aradaki fark, ücretlerden bağımsız olarak doğrudan kaybınızdır. Makas genellikle fiyatın yüzdesi veya baz puan olarak ifade edilir.",["Likit paritelerde, örneğin büyük borsalardaki ",["BTC","bitcoin"],"/",["USDT","usdt"],"'de, makas çok dardır. Düşük hacimli ",["altcoin","altcoin"],"'lerde, gece saatlerinde veya sert haber anlarında makas genişler. Piyasa yapıcılar (market maker) sürekli alış ve satış emri vererek makası daraltır."],"Bazı uygulamalar ücretsiz işlem diye tanıtılan hızlı al-sat ekranlarında maliyeti makasın içine gizler. Gerçek maliyeti görmek için işlem ücretini, makası ve kaymayı birlikte değerlendirmeniz gerekir."],"example":"Bir altcoin'de en iyi alış fiyatı 2,490 USDT, en iyi satış fiyatı 2,510 USDT olsun. Makas 0,02 USDT'dir; orta fiyat 2,50 olduğu için bu yüzde 0,8 eder. 1.000 USDT ile piyasa emriyle alıp hemen piyasa emriyle satarsanız, ücretler hariç yaklaşık 8 USDT kaybedersiniz. BTC/USDT gibi likit bir paritede makas yüzde 0,01'in altındaysa aynı gidiş-dönüş işlemin makas maliyeti 0,1 USDT'nin altında kalır.","mistakes":["Yalnızca işlem ücretine bakıp makasın maliyetini görmezden gelmek.","Makasın geniş olduğu düşük hacimli saatlerde piyasa emriyle işlem yapmak.","Ücretsiz olarak sunulan hızlı al-sat ekranlarının fiyat farkını kontrol etmemek."],"faq":[{"q":"Spread neden genişler?","a":"Likidite azaldığında, yani defterde az emir olduğunda veya ani haberlerle oynaklık arttığında piyasa yapıcılar riski azaltmak için makası genişletir."},{"q":"Makas maliyetinden nasıl kaçınılır?","a":"Limit emir kullanarak kendi fiyatınızı belirleyebilir ve makası geçmek yerine defterde bekleyebilirsiniz. Likit pariteleri ve yoğun saatleri tercih etmek de makası daraltır."}],"title":"Alış-satış makası (spread) nedir?","description":"Kriptoda alış-satış makasının ne olduğunu, nasıl hesaplandığını ve işlem maliyetinizi nasıl artırdığını örnekle öğrenin.","related":[["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["market-maker","Piyasa yapıcı (Market maker)","Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir."],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Ekrandaki fiyat neden benim gerçekleşen fiyatım değil?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"tr","term":"Kayma (slippage)","aka":["slippage","fiyat kayması"],"short":"Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar.","body":[["Merkezi borsada ",["piyasa emri","market-order"]," verdiğinizde emir defterindeki en iyi fiyatlı emirlerle sırayla eşleşirsiniz. İlk seviyedeki miktar yetmezse emriniz bir sonraki, daha kötü fiyata geçer. Ortalama fiyatınız ekranda gördüğünüz fiyattan uzaklaşır; bu fark kaymadır."],["Merkeziyetsiz borsalarda (",["AMM","amm"],") kayma, havuzdaki token oranının işleminizle değişmesinden kaynaklanır. Cüzdanlar bu yüzden bir kayma toleransı ayarı sunar; fiyat bu yüzdeden fazla kötüleşirse işlem iptal edilir. Toleransı çok yüksek tutmak, sandviç saldırılarına (",["MEV","mev"],") açık kapı bırakabilir."],["Kayma yalnızca alımda değil, satımda ve zarar durdur emirlerinde de görülür. Sert bir düşüşte tetiklenen stop-market emri, belirlediğiniz seviyenin oldukça altında dolabilir. Likit pariteleri seçmek, büyük emirleri bölmek ve ",["limit emir","limit-order"]," kullanmak kaymayı azaltır."]],"example":["Bir ",["DEX","dex"]," havuzunda 500.000 ",["USDC","usdc"]," ve 200 ETH olduğunu, yani fiyatın 2.500 USDC olduğunu varsayalım. 25.000 USDC ile ETH alırsanız, sabit çarpım formülüne göre havuz 525.000 USDC ve yaklaşık 190,48 ETH'ye geçer; siz yaklaşık 9,52 ETH alırsınız. Ortalama fiyatınız 25.000 / 9,52 = yaklaşık 2.625 USDC olur, yani beklenen fiyata göre yaklaşık yüzde 5 kayma. Aynı alımı 2.500 USDC ile yapsaydınız kayma yalnızca yüzde 0,5 civarında kalırdı. Havuz ücreti bu hesaba ayrıca eklenir."],"mistakes":["DEX'te kayma toleransını yüzde 10-20 gibi yüksek değerlere ayarlayıp sandviç saldırısına açık kalmak.","Düşük likiditeli bir coinde büyük tutarı tek bir piyasa emriyle almak.","Kaymanın yalnızca alımda olduğunu sanıp zarar durdur emirlerindeki etkisini hesaba katmamak."],"faq":[{"q":"Slippage toleransı kaç olmalı?","a":"Likit paritelerde yüzde 0,5 veya altı çoğu zaman yeterlidir. Oynak ve sığ token'larda daha yüksek değer gerekebilir, ancak tolerans arttıkça kötü fiyattan dolma ve MEV riski de artar."},{"q":"Pozitif kayma olur mu?","a":"Evet. Emir verilirken fiyat sizin lehinize hareket ederse beklenenden daha iyi bir fiyattan dolabilirsiniz. Ancak hızlı piyasalarda genellikle negatif kayma daha sık görülür."}],"title":"Kayma (slippage) nedir? Nasıl azaltılır?","description":"Slippage'ın ne olduğunu, CEX ve DEX'te nasıl oluştuğunu ve kayma toleransını nasıl ayarlamanız gerektiğini örnekle öğrenin.","related":[["bid-ask-spread","Alış-satış makası (spread)","Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Ekrandaki fiyat neden benim gerçekleşen fiyatım değil?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"tr","term":"İz süren stop (trailing stop)","aka":["trailing stop","takip eden stop","iz süren zarar durdur"],"short":"İz süren stop (trailing stop), fiyat lehinize hareket ettikçe tetik seviyesini otomatik olarak belirli bir yüzde veya tutar kadar geriden takip ettiren, fiyat geri döndüğünde ise pozisyonu kapatan bir emirdir.","body":[["Normal ",["zarar durdur emri","stop-loss"]," sabit bir seviyede bekler. İz süren stopta ise bir mesafe belirlersiniz, örneğin yüzde 5. Fiyat yükseldikçe stop seviyesi en yüksek fiyatın yüzde 5 altına taşınır; fiyat düştüğünde ise stop yerinde kalır ve aşağı inmez."],"Bu yapı, yükselen bir trendde kârın bir kısmını kilitlerken trendin devam etmesine izin verir. Bazı borsalarda bir aktivasyon fiyatı da girebilirsiniz; iz sürme ancak fiyat bu seviyeye ulaştıktan sonra başlar.",["Mesafeyi seçmek kritik önemdedir. Çok dar bir mesafe, sıradan dalgalanmalarla erken çıkmanıza neden olur; çok geniş bir mesafe ise kârın büyük kısmını geri vermenize yol açar. Tetiklendiğinde emir genellikle ",["piyasa emri","market-order"]," olarak gider, bu yüzden hızlı düşüşlerde ",["kayma","slippage"]," görülebilir."]],"example":["Bir coini 100 ",["USDT","usdt"],"'den aldınız ve yüzde 8 mesafeli bir iz süren stop koydunuz. Başlangıçta stop 92 USDT'dedir. Fiyat 130 USDT'ye çıkınca stop 130 x 0,92 = 119,6 USDT'ye yükselir. Fiyat daha sonra 125'e geri çekilirse stop 119,6'da kalır. Fiyat 119,6'ya düştüğünde emir tetiklenir ve pozisyon kapanır; 100'den alıp yaklaşık 119,6'dan sattığınız için kayma hariç yaklaşık yüzde 19,6 kâr elde edersiniz. Zirve olan 130'a göre yaklaşık 10,4 USDT'lik hareketi geri vermiş olursunuz."],"mistakes":["Coinin günlük oynaklığından daha dar bir iz sürme mesafesi seçmek.","İz süren stopun fiyat düştüğünde de aşağı ineceğini sanmak.","Tetiklenen emrin piyasa emri olduğunu ve hızlı düşüşlerde kayma olabileceğini unutmak."],"faq":[{"q":"Trailing stop yüzdesi kaç olmalı?","a":"Tek bir doğru değer yoktur; coinin tipik oynaklığına ve zaman diliminize göre seçilir. Günlük hareketi yüzde 5 olan bir coinde yüzde 2'lik mesafe genellikle çok dardır."},{"q":"Trailing stop her borsada var mı?","a":"Birçok büyük borsa bu emir türünü spot veya vadeli işlemlerde sunar, ancak adı, aktivasyon fiyatı seçeneği ve hangi fiyatı takip ettiği borsadan borsaya değişir."}],"title":"Trailing stop (iz süren stop) nedir?","description":"İz süren stopun nasıl çalıştığını, kârı nasıl kilitlediğini ve doğru takip mesafesini nasıl seçeceğinizi örnekle öğrenin.","related":[["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."],["stop-limit-order","Stop-limit emir","Stop-limit emir, fiyat belirlediğiniz tetik (stop) seviyesine ulaştığında, önceden tanımladığınız fiyattan bir limit emir gönderen ve böylece kötü fiyattan dolmayı engelleyen koşullu bir emirdir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"tr","term":"İşaret fiyatı (Mark price)","aka":["mark price","adil fiyat","referans fiyat"],"short":"İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır.","body":[["Bir kontratın ",["son işlem fiyatı","last-price"],", tek bir büyük emirle veya ince bir defterde anlık olarak çok sapabilir. ",["Likidasyon","liquidation"]," bu fiyata göre yapılsaydı, kısa süreli bir iğne binlerce pozisyonu haksız yere tasfiye edebilirdi. İşaret fiyatı bu riski azaltmak için kullanılır."],["İşaret fiyatı genellikle birden fazla spot borsadan alınan ",["endeks fiyatı","index-price"]," temel alınarak hesaplanır ve buna ",["fonlama oranı","funding-rate"]," veya kontrat ile endeks arasındaki farkın hareketli ortalaması gibi bir düzeltme eklenir. Kesin formül borsadan borsaya değişir."],"Pratikte bilmeniz gereken şudur: gerçekleşmemiş kâr-zararınız ve likidasyon fiyatınız işaret fiyatına göre izlenir. Stop emirleri için ise birçok borsa tetikleyici olarak son fiyat veya işaret fiyatı seçmenize izin verir. Grafikte işaret fiyatını ayrıca gösterecek şekilde ayar yapmak faydalıdır."],"example":[["BTC","bitcoin"]," ",["perpetual","perpetual-futures"]," kontratında son işlem fiyatı, büyük bir satış emriyle birkaç saniyeliğine 61.200 USDT'ye iniyor. Aynı anda spot borsalardan hesaplanan endeks fiyatı 62.400, işaret fiyatı ise 62.380 USDT. Likidasyon fiyatı 61.500 olan bir long pozisyon, son fiyat bu seviyenin altına inmesine rağmen tasfiye edilmez, çünkü işaret fiyatı 880 USDT yukarıda kalır. Son fiyat kısa sürede toparlanırsa pozisyonunuz açık kalmaya devam eder."],"mistakes":["Grafikte yalnızca son işlem fiyatını izleyip likidasyonun işaret fiyatına göre olduğunu unutmak.","Gerçekleşmemiş kâr-zararın neden son fiyattan farklı hesaplandığını anlamamak.","İşaret fiyatının her borsada aynı formülle hesaplandığını varsaymak."],"faq":[{"q":"İşaret fiyatı ile son fiyat neden farklı?","a":"Son fiyat o kontratta gerçekleşen son işlemdir ve anlık olarak sapabilir. İşaret fiyatı ise birden fazla borsadaki spot fiyatlara dayanır ve daha istikrarlıdır."},{"q":"Stop-loss işaret fiyatına mı son fiyata mı göre tetiklenir?","a":"Birçok borsa bunu seçmenize izin verir. İşaret fiyatı ani iğnelere karşı daha az hassastır, son fiyat ise gerçek işlem akışını daha hızlı yansıtır."}],"title":"İşaret fiyatı (mark price) nedir? Neden önemli","description":"Vadeli işlemlerde işaret fiyatının nasıl hesaplandığını ve likidasyonu neden son fiyat yerine onun tetiklediğini öğrenin.","related":[["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır."],["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir."],["last-price","Son işlem fiyatı (Last traded price)","Son işlem fiyatı, bir borsadaki belirli bir paritede veya kontratta en son gerçekleşen alım-satım işleminin fiyatıdır."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"tr","term":"Dönüştür (anında çevirme)","aka":["Convert","dönüştür","anında takas","instant swap"],"short":"Dönüştür (Convert), borsada emir defteriyle uğraşmadan bir coin'i başka bir coin'e tek ekranda, size önceden gösterilen sabit bir kur üzerinden anında çevirmenizi sağlayan özelliktir.","body":[["Spot piyasada limit veya ",["piyasa emri","market-order"]," verir, emir defterinde bekler ya da ",["kayma (slippage)","slippage"]," yaşarsınız. Dönüştür ekranında ise 'şu kadar ",["BTC","bitcoin"]," ver, şu kadar ",["USDT","usdt"]," al' şeklinde bir teklif görürsünüz. Teklif birkaç saniye geçerlidir; onaylarsanız işlem o kurdan yapılır."],["Birçok borsa Convert için ayrıca ",["işlem ücreti","gas-fee"]," göstermez. Ancak maliyet çoğu zaman kurun içindedir: size verilen fiyat, spot piyasadaki fiyattan biraz daha kötü olabilir. Bu fark küçük tutarlarda önemsiz görünür, büyük tutarlarda belirgin hâle gelir."],["Dönüştür, likiditesi düşük çiftlerde veya hızlı küçük çevirmelerde pratiktir. Büyük tutarlarda ",["spot piyasa","spot-trading"]," ile karşılaştırma yapmak ve gerekiyorsa limit emir kullanmak genellikle daha ucuzdur."]],"example":"Spot piyasada ETH'nin 3.000 USDT ve işlem ücretinin yüzde 0,1 olduğunu varsayalım. 2 ETH'yi spot piyasada satarsanız 6.000 USDT'den 6 USDT ücret düşülür ve 5.994 USDT alırsınız. Dönüştür ekranı 'ücretsiz' yazıyor ama 1 ETH için 2.991 USDT teklif ediyor. 2 ETH için 5.982 USDT alırsınız. Görünürde ücret ödemediğiniz hâlde spot piyasaya göre 12 USDT daha az almış olursunuz.","mistakes":["'Sıfır ücret' yazısını görünce toplam maliyeti spot piyasa ile karşılaştırmamak.","Büyük tutarları tek seferde Convert ile çevirmek.","Teklif süresi dolduktan sonra yenilenen kuru kontrol etmeden onaylamak."],"faq":[{"q":"Convert ücretsiz mi?","a":"Birçok borsa ayrı bir işlem ücreti göstermez, ancak maliyet genellikle teklif edilen kurun içindedir. Gerçek maliyeti görmek için aynı anda spot fiyatla karşılaştırmak gerekir."},{"q":"Dönüştür mü spot işlem mi daha iyi?","a":"Küçük ve hızlı çevirmelerde Dönüştür pratiktir. Büyük tutarlarda spot piyasada limit emir kullanmak çoğu zaman daha iyi fiyat sağlar."}],"title":"Convert (Dönüştür) nedir? Anında kripto çevirme","description":"Borsalardaki Convert (Dönüştür) özelliği nedir, sıfır ücret iddiası neden yanıltıcı olabilir ve spot işlemle farkı nedir, öğrenin.","related":[["spot-trading","Spot işlem (spot trading)","Spot işlem, bir kripto parayı o anki piyasa fiyatından alıp satarak varlığın kendisine anında sahip olduğunuz, kaldıraç ve vade içermeyen temel alım satım türüdür."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["bid-ask-spread","Alış-satış makası (spread)","Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"İlk spot işlemin: 100'den 0.002 BTC'ye"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"tr","term":"Tokenize hisse senetleri","aka":["tokenize hisse","tokenized stocks","hisse token'ı","zincir üstü hisse"],"short":"Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır.","body":["Bir ihraççı gerçek hisseleri satın alıp bir saklayıcıda tutar ve her hisse için zincir üstünde bir token çıkarır. Token, hisse fiyatını takip eder. Bazı ürünler kriptonun 7/24 piyasasında işlem görür, bazıları kesirli alım imkânı verir; yani 1 hisse yerine 0,1 hisse alabilirsiniz.","Önemli olan, token'ın size hangi hakları verdiğidir. Çoğu üründe oy hakkınız yoktur, temettü ise ürüne göre token olarak dağıtılabilir veya fiyata yansıtılabilir. Ayrıca ihraççının ve saklayıcının güvenilirliğine bağlı olursunuz. Bu ürünler ülkelere göre farklı düzenlemelere tabidir ve bazı bölgelerde sunulmaz.","Hisse piyasası kapalıyken token işlem görmeye devam edebilir. Bu dönemlerde fiyat, piyasa açıldığında oluşacak fiyattan sapabilir ve açılışta ani düzeltmeler görülebilir."],"example":["Bir hisse token'ının, hissesi 200 dolar olan bir şirketi takip ettiğini varsayalım. 500 ",["USDT","usdt"]," ile 2,5 token alırsınız. Cumartesi günü olumsuz bir haber çıkar ve token kripto piyasasında 190 dolara düşer; bakiyeniz 475 USDT görünür. Pazartesi hisse borsası 185 dolardan açılır ve token bu fiyata yaklaşır, bakiyeniz 462,5 USDT olur. Şirket hisse başına 1 dolar temettü dağıtırsa ve ürün temettüyü yansıtıyorsa 2,5 USDT eklenir."],"mistakes":["Tokenize hissenin size gerçek hissedar hakları verdiğini varsaymak.","Piyasa kapalıyken oluşan fiyatın açılışta aynı kalacağını düşünmek.","İhraççının, saklayıcının ve ürünün ülkenizde sunulup sunulmadığını kontrol etmemek."],"faq":[{"q":"Tokenize hisse ile gerçek hisse aynı şey mi?","a":"Fiyat olarak benzer hareket eder, ancak hukuki haklar farklı olabilir. Çoğu tokenize hissede oy hakkı yoktur ve ihraççının yapısına bağlı kalırsınız."},{"q":"Tokenize hisseler hafta sonu işlem görür mü?","a":"Birçoğu kripto piyasasında 7/24 işlem görebilir. Ancak hisse borsası kapalıyken likidite düşük olabilir ve fiyat açılışta düzelebilir."}],"title":"Tokenize hisse senedi nedir? Zincir üstü hisseler","description":"Tokenize hisse senetleri nedir, gerçek hisseden farkı nedir, temettü ve oy hakkı nasıl işler ve hafta sonu fiyatı neden sapar.","related":[["stock-perpetuals","Hisse senedi sürekli vadelileri (stock perpetuals)","Hisse senedi sürekli vadelileri, bir hissenin fiyatını takip eden, vadesi olmayan ve genellikle USDT ile teminatlandırılan, kaldıraçla long veya short açılabilen kripto borsası türev kontratlarıdır."],["real-world-assets","Gerçek dünya varlıkları (RWA)","Gerçek dünya varlıkları (RWA), devlet tahvilleri, altın, gayrimenkul, krediler veya hisseler gibi blockchain dışındaki varlıkların zincir üstünde token olarak temsil edilmesidir."],["spot-bitcoin-etf","Spot Bitcoin ETF","Spot Bitcoin ETF, gerçek bitcoin satın alıp saklayan ve borsada hisse senedi gibi işlem gören, fiyatı bitcoin'in piyasa fiyatını takip eden bir borsa yatırım fonudur."],["usdc","USDC (USD Coin)","USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
